<?php
require_once __DIR__ . '/../bootstrap.php'; require_admin();$q=trim($_GET['q']??'');$sql='SELECT id,full_name,email,phone,role,created_at FROM users';$params=[];if($q!==''){$sql.=' WHERE full_name LIKE ? OR email LIKE ? OR phone LIKE ?';$params=["%$q%","%$q%","%$q%"];}$sql.=' ORDER BY created_at DESC';$st=$conn->prepare($sql);$st->execute($params);$users=$st->fetchAll(PDO::FETCH_ASSOC);admin_header('Quản lý người dùng'); ?>
<div class="card"><div class="toolbar"><form class="search" method="get"><input class="form-control" name="q" placeholder="Tìm tên, email hoặc số điện thoại..." value="<?= h($q) ?>"><button class="btn" type="submit">Tìm kiếm</button></form></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Họ tên</th><th>Email</th><th>Điện thoại</th><th>Vai trò</th><th>Ngày tạo</th><th>Thao tác</th></tr></thead><tbody><?php if(!$users): ?><tr><td colspan="7" class="empty">Không tìm thấy người dùng.</td></tr><?php else: foreach($users as $u): ?><tr><td><?= (int)$u['id'] ?></td><td><?= h($u['full_name']) ?></td><td><?= h($u['email']) ?></td><td><?= h($u['phone']) ?></td><td><span class="badge"><?= h($u['role']) ?></span></td><td><?= h($u['created_at']) ?></td><td><?php if($u['role']!=='admin'): ?><form method="post" action="<?= h(admin_url('users/delete.php')) ?>" onsubmit="return confirm('Bạn chắc chắn muốn xóa tài khoản này?');"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="btn btn-danger btn-small" type="submit">Xóa</button></form><?php else: ?><span class="text-muted">Tài khoản Admin</span><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div><?php admin_footer(); ?>
